export function resolveIndexedJapanUrls(code: string): string[] {
  const pStr = JAPAN_LAZ_INDEX[code];
  if (!pStr) return [];
  const zone = code.slice(0, 2);
  const letterPair = code.slice(2, 4);
  const sheet5k = code.slice(4, 6);
  const relative = `${zone}/${letterPair}/${sheet5k}/${code}.zip`;
  const urls: string[] = [];
  for (let i = 0; i < pStr.length; i++) {
    const idx = parseInt(pStr[i], 10);
    const prefix = JAPAN_PREFIXES[idx];
    if (prefix) urls.push(`${prefix}${relative}`);
  }
  return urls;
}
